{
  "case_id": "xsu_sg_008_completed_treatment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner ikke minimumskravet om journaler fra egen læge, speciallæge, hospital eller ambulant klinik (§ 37, stk. 3). Det beskriver epikrise/afsluttende journalnotat som det første vedlæg uden at sige, at det er et udgangspunkt. Det tilføjer krav, der ikke er i kilderne: en aktuel lægelig vurdering med prognose og en beskrivelse af, hvorfor tilstanden gør studiejob vanskeligt. Derudover er formuleringerne om, at en kort erklæring fra egen læge kan være utilstrækkelig, og at 'SU vurderer sagen samlet', ikke direkte forankret i kilderne."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element mangler: journalmateriale fra egen læge, speciallæge, hospital eller ambulant klinik som minimum. Epikrise nævnes, men ikke som 'som udgangspunkt'. Kravet om, at materialet skal beskrive den varige funktionsnedsættelse, er kun delvist dækket, fordi svaret taler om funktionsnedsættelse og varighed i prognosen, men ikke eksplicit om 'varig'."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken lægelig dokumentation der bør vedlægges, når behandlingen er afsluttet."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret henviser ikke til nogen identificerbar kilde som lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så det kan ikke vurderes, om kilder understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer krav og vurderinger uden støtte i materialet: aktuel lægelig vurdering med prognose og forventet varighed som vedlæg, beskrivelse af konkrete følger i hverdagen og hvorfor studiejob er vanskeligt, samt at en kort erklæring fra egen læge kan være utilstrækkelig. Kilderne kræver aktuel dokumentation med lægefaglige oplysninger om art og grad (§ 37, stk. 4), men ikke prognose eller konkrete hverdagsfølger som dokumentationskrav."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Forbeholdet 'som udgangspunkt' ved epikrise/afslutningsbrev er ikke bevaret. Svaret siger heller ikke, at titlen alene ikke afgør tilstrækkeligheden, selvom det delvist nævner, at en epikrise ikke i sig selv er nok. Minimumskravet om journaler mangler."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: dokumentationen skal vise tilstand, forløb og aktuel påvirkning, og diagnose eller afsluttet behandling er ikke nok alene. Der er ingen indre modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'bør' og 'så vidt muligt' om en række ting, som kilderne ikke formulerer sådan, og udelader kildens 'skal som minimum' for journalmaterialet. Epikrise præsenteres uden 'som udgangspunkt', og elementer uden kildestøtte fremstilles som anbefalinger. Det gengiver ikke kildens modalitet præcist."
    }
  },
  "xhaile_coverage": {
    "A30": {
      "label": "partial",
      "reason": "Svaret angiver, at man ved afsluttet behandling bør vedlægge epikrise eller afsluttende journalnotat, men gengiver ikke 'som udgangspunkt' og ikke vejledningens formulering om, at dokumentationen vil indeholde det."
    },
    "A32": {
      "label": "partial",
      "reason": "Epikrise eller afsluttende journalnotat nævnes som dokumentation. Svaret udtrykker dog ikke den præcise regel om 'som udgangspunkt' og forbinder den ikke med vejledningens minimumskrav."
    }
  },
  "overall_notes": "Svaret er relevant og praktisk, men udelader minimumskravet om journalmateriale fra de nævnte behandlertyper. Det tilføjer ikke-kildebelagte dokumentationskrav (prognose, hverdagsfølger) og citerer ingen kilder. Epikrise er nævnt, men uden forbeholdet 'som udgangspunkt'."
}

